def generate_strings(n, a):
    strings = [''] * (n + 1)
    strings[0] = 'a' * (a[0] + 1)
    for i in range(n):
        if a[i] == 0:
            strings[i + 1] = 'a' * (a[i] + 1)
        else:
            strings[i + 1] = strings[i][:a[i]] + 'a' * (len(strings[i]) - a[i])
    return strings

